#include <string>
#include <vector>

class Solution {
public:
    std::string firstPalindrome(std::vector<std::string>& words) {
        for (const auto& w : words) {
            int l = 0, r = (int)w.size() - 1;
            bool ok = true;
            while (l < r) {
                if (w[l++] != w[r--]) {
                    ok = false;
                    break;
                }
            }
            if (ok) return w;
        }
        return "";
    }
};

class Solution {
    public String firstPalindrome(String[] words) {
        for (String w : words) {
            int l = 0, r = w.length() - 1;
            boolean ok = true;
            while (l < r) {
                if (w.charAt(l++) != w.charAt(r--)) {
                    ok = false;
                    break;
                }
            }
            if (ok) return w;
        }
        return "";
    }
}

